import express from 'express';
import pg from 'pg';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import fs from 'fs';
import PDFDocument from 'pdfkit';

const app=express(),port=Number(process.env.PORT||3000);
const pool=new pg.Pool({connectionString:process.env.DATABASE_URL});
const secret=process.env.JWT_SECRET||'dev-secret-change-me';
app.use(express.json({limit:'2mb'})); app.use(express.static('public'));

async function init(){
  await pool.query(fs.readFileSync('./schema.sql','utf8'));
  const email=process.env.SAAS_ADMIN_EMAIL||'admin@owltechsolutionsltd.com';
  const password=process.env.SAAS_ADMIN_PASSWORD||'ChangeMeNow123!';
  let q=await pool.query('SELECT id FROM users WHERE lower(email)=lower($1)',[email]);
  let uid;
  if(!q.rowCount){const hash=await bcrypt.hash(password,12);const x=await pool.query('INSERT INTO users(email,password_hash,name,role) VALUES($1,$2,$3,$4) RETURNING id',[email,hash,'SaaS Administrator','saas_admin']);uid=x.rows[0].id}else uid=q.rows[0].id;
}
function auth(req,res,next){
  const h=req.headers.authorization||'',t=h.startsWith('Bearer ')?h.slice(7):null;
  if(!t)return res.status(401).json({error:'Unauthorized'});
  try{req.user=jwt.verify(t,secret);next()}catch{return res.status(401).json({error:'Invalid session'})}
}
async function tenant(req,res,next){
  if(req.user.role==='saas_admin'){req.businessId=Number(req.headers['x-business-id']||0)||null;return next()}
  const q=await pool.query('SELECT ub.business_id,b.status,b.trial_ends_at FROM user_businesses ub JOIN businesses b ON b.id=ub.business_id WHERE ub.user_id=$1 AND ub.active=true ORDER BY ub.business_id LIMIT 1',[req.user.id]);
  if(!q.rowCount)return res.status(403).json({error:'No active tenant'});
  req.businessId=q.rows[0].business_id; req.tenant=q.rows[0]; next();
}

async function getBusinessRole(req,bid){
  if(req.user.role==='saas_admin')return 'saas_admin';
  const q=await pool.query('SELECT role FROM user_businesses WHERE user_id=$1 AND business_id=$2 AND active=true',[req.user.id,bid]);
  return q.rows[0]?.role||null;
}
async function approvalTarget(client,bid,actionType){
  const r=await client.query('SELECT * FROM approval_rules WHERE business_id=$1 AND action_type=$2 AND active=true',[bid,actionType]);
  if(!r.rowCount)return {approverUserId:null,approverRole:'owner'};
  return {approverUserId:r.rows[0].approver_user_id||null,approverRole:r.rows[0].approver_role||'owner'};
}
async function canDecideApproval(client,req,bid,approval){
  if(req.user.role==='saas_admin')return true;
  if(approval.approver_user_id&&Number(approval.approver_user_id)===Number(req.user.id))return true;
  const q=await client.query('SELECT role FROM user_businesses WHERE user_id=$1 AND business_id=$2 AND active=true',[req.user.id,bid]);
  const role=q.rows[0]?.role||'';
  if(['owner','admin'].includes(role))return true;
  return approval.approver_role?role===approval.approver_role:false;
}

async function getBiz(req){if(req.businessId)return req.businessId;const q=await pool.query('SELECT id FROM businesses ORDER BY id LIMIT 1');return q.rows[0]?.id}
async function audit(user,businessId,action,entity,id,details={}){try{await pool.query('INSERT INTO audit_logs(user_email,business_id,action,entity,entity_id,details) VALUES($1,$2,$3,$4,$5,$6)',[user?.email||null,businessId||null,action,entity,id?String(id):null,details])}catch{}}
app.get('/api/health',async(req,res)=>{try{await pool.query('SELECT 1');res.json({ok:true,database:'postgresql'})}catch(e){res.status(500).json({ok:false,error:e.message})}});

app.post('/api/register',async(req,res)=>{
  const {name,email,password,businessName,country='Uganda',currency='UGX'}=req.body||{};
  if(!name||!email||!password||!businessName)return res.status(400).json({error:'All fields are required'});
  const client=await pool.connect();
  try{
    await client.query('BEGIN');
    const exists=await client.query('SELECT 1 FROM users WHERE lower(email)=lower($1)',[email]); if(exists.rowCount)throw new Error('Email already registered');
    const hash=await bcrypt.hash(password,12);
    const u=await client.query('INSERT INTO users(email,password_hash,name,role) VALUES($1,$2,$3,$4) RETURNING id,email,name,role',[email,hash,name,'tenant_owner']);
    const b=await client.query("INSERT INTO businesses(name,country,currency,status,trial_ends_at) VALUES($1,$2,$3,'trial',now()+interval '14 days') RETURNING *",[businessName,country,currency]);
    await client.query('INSERT INTO user_businesses(user_id,business_id,role) VALUES($1,$2,$3)',[u.rows[0].id,b.rows[0].id,'owner']);
    await client.query("INSERT INTO tenant_modules(business_id,module_code,enabled,trial,expires_at) SELECT $1,code,true,(NOT core),CASE WHEN core THEN NULL ELSE now()+interval '14 days' END FROM module_catalog",[b.rows[0].id]);
    await client.query('INSERT INTO branches(business_id,name,location) VALUES($1,$2,$3)',[b.rows[0].id,'Main Branch',country]);await client.query("INSERT INTO approval_rules(business_id,section,action_type,approver_role) VALUES($1,'Purchasing','purchase_order','owner'),($1,'Inventory','inventory_wastage','owner'),($1,'Inventory','inventory_spoilage','owner'),($1,'Restaurant','restaurant_order_cancel','owner'),($1,'Sales','transaction_discount','owner'),($1,'Sales','transaction_foc','owner') ON CONFLICT(business_id,action_type) DO NOTHING",[b.rows[0].id]);
    await client.query('COMMIT');
    const token=jwt.sign({id:u.rows[0].id,email:u.rows[0].email,name:u.rows[0].name,role:u.rows[0].role,businessId:b.rows[0].id},secret,{expiresIn:'7d'});
    res.json({token,user:u.rows[0],business:b.rows[0],trialDays:14});
  }catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}
});
app.post('/api/login',async(req,res)=>{
  const {email,password}=req.body||{}; const q=await pool.query('SELECT * FROM users WHERE lower(email)=lower($1) AND active=true',[email||'']);
  if(!q.rowCount||!(await bcrypt.compare(password||'',q.rows[0].password_hash)))return res.status(401).json({error:'Invalid email or password'});
  const u=q.rows[0]; let businessId=null;
  if(u.role!=='saas_admin'){const m=await pool.query('SELECT business_id FROM user_businesses WHERE user_id=$1 AND active=true ORDER BY business_id LIMIT 1',[u.id]);businessId=m.rows[0]?.business_id||null}
  const token=jwt.sign({id:u.id,email:u.email,name:u.name,role:u.role,businessId},secret,{expiresIn:'7d'});
  await audit(u,businessId,'login','user',u.id); res.json({token,user:{id:u.id,email:u.email,name:u.name,role:u.role,businessId}});
});
