app.put('/api/restaurant/orders/:id/items/:itemId',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),itemId=Number(req.params.itemId),{qty,notes}=req.body||{};if(!(Number(qty)>0))return res.status(400).json({error:'Quantity must be positive'});const client=await pool.connect();try{await client.query('BEGIN');const o=await client.query('SELECT status FROM restaurant_orders WHERE id=$1 AND business_id=$2 FOR UPDATE',[id,bid]);if(!o.rowCount)throw new Error('Order not found');if(['sent_to_kitchen','preparing','ready','served','bill_requested','partially_paid','paid','closed','cancelled'].includes(o.rows[0].status))throw new Error('Item quantity cannot be changed after the order has been sent to kitchen');const old=await client.query('SELECT qty FROM restaurant_order_items WHERE id=$1 AND order_id=$2 FOR UPDATE',[itemId,id]);if(!old.rowCount)throw new Error('Order item not found');const ratio=Number(qty)/Number(old.rows[0].qty);await client.query('UPDATE restaurant_order_items SET qty=$1,line_total=unit_price*$1,notes=$2 WHERE id=$3',[Number(qty),notes||null,itemId]);await client.query('UPDATE restaurant_order_item_modifiers SET qty=qty*$1,line_total=unit_price*(qty*$1) WHERE order_item_id=$2',[ratio,itemId]);await recalcRestaurantOrder(client,id);await client.query('COMMIT');res.json({ok:true})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
