app.post('/api/restaurant/orders/:id/hold',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const q=await pool.query("UPDATE restaurant_orders SET held=true,updated_at=now() WHERE id=$1 AND business_id=$2 AND status NOT IN ('closed','cancelled') RETURNING *",[id,bid]);if(!q.rowCount)return res.status(400).json({error:'Order cannot be held'});res.json(q.rows[0])});
app.post('/api/restaurant/orders/:id/resume',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const q=await pool.query("UPDATE restaurant_orders SET held=false,updated_at=now() WHERE id=$1 AND business_id=$2 AND status NOT IN ('closed','cancelled') RETURNING *",[id,bid]);if(!q.rowCount)return res.status(400).json({error:'Order cannot be resumed'});res.json(q.rows[0])});
app.post('/api/restaurant/orders/:id/transition',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),to=String(req.body?.status||''),comment=req.body?.comment||null;const allowed={open:[],sent_to_kitchen:[],preparing:[],ready:[],served:['bill_requested'],bill_requested:[],partially_paid:[],paid:['closed']};const client=await pool.connect();try{await client.query('BEGIN');const o=await client.query('SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 FOR UPDATE',[id,bid]);if(!o.rowCount)throw new Error('Order not found');if(!(allowed[o.rows[0].status]||[]).includes(to))throw new Error('Invalid order status transition from '+o.rows[0].status+' to '+to);await client.query("UPDATE restaurant_orders SET status=$1,held=false,updated_at=now(),closed_at=CASE WHEN $1 IN ('closed','cancelled') THEN now() ELSE closed_at END WHERE id=$2",[to,id]);await client.query('INSERT INTO restaurant_order_status_history(order_id,from_status,to_status,comment,changed_by) VALUES($1,$2,$3,$4,$5)',[id,o.rows[0].status,to,comment,req.user.name]);if(to==='bill_requested'&&o.rows[0].table_id)await client.query("UPDATE restaurant_tables SET status='waiting_for_bill' WHERE id=$1",[o.rows[0].table_id]);if(['closed','cancelled'].includes(to))await freeRestaurantTableIfUnused(client,bid,o.rows[0].table_id,id);await client.query('COMMIT');res.json({ok:true,status:to})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});


app.post('/api/restaurant/orders/:id/deposits',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),lines=req.body?.payments||[],client=await pool.connect();try{await client.query('BEGIN');const oq=await client.query("SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 AND status NOT IN ('closed','cancelled','paid','bill_requested','partially_paid') FOR UPDATE",[id,bid]);if(!oq.rowCount)throw new Error('Order is not eligible for a deposit');const order=oq.rows[0];const posted=await postPaymentLines(client,{bid,branchId:order.branch_id,customerId:order.customer_id,sourceType:'restaurant_order',sourceId:id,total:order.total,lines,userName:req.user.name});await client.query('UPDATE restaurant_orders SET amount_paid=$1,balance_due=$2,updated_at=now() WHERE id=$3',[posted.paid,posted.balance,id]);await client.query('COMMIT');await audit(req.user,bid,'deposit','restaurant_order',id,{amount:posted.posted.reduce((n,x)=>n+Number(x.amount),0),amountPaid:posted.paid,balanceDue:posted.balance});res.json({ok:true,amountPaid:posted.paid,balanceDue:posted.balance,payments:posted.posted})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.get('/api/restaurant/orders/:id/bill',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id);const o=await pool.query("SELECT ro.*,t.name table_name,c.name customer_name FROM restaurant_orders ro LEFT JOIN restaurant_tables t ON t.id=ro.table_id LEFT JOIN customers c ON c.id=ro.customer_id WHERE ro.id=$1 AND ro.business_id=$2",[id,bid]);if(!o.rowCount)return res.status(404).json({error:'Order not found'});const summary=await paymentSummaryForSource(pool,bid,'restaurant_order',id);res.json({order:o.rows[0],payments:summary.payments,amountPaid:summary.total,balanceDue:Math.max(0,Number(o.rows[0].total)-summary.total)})});

app.post('/api/restaurant/orders/:id/payments',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),lines=req.body?.payments||[],client=await pool.connect();try{await client.query('BEGIN');const oq=await client.query("SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 AND status NOT IN ('closed','cancelled') FOR UPDATE",[id,bid]);if(!oq.rowCount)throw new Error('Restaurant order not found');let order=oq.rows[0];if(!['served','bill_requested','partially_paid'].includes(order.status))throw new Error('Order must be served before payment can be taken');if(order.status==='served'){await client.query("UPDATE restaurant_orders SET status='bill_requested',held=false,updated_at=now() WHERE id=$1",[id]);await client.query("INSERT INTO restaurant_order_status_history(order_id,from_status,to_status,comment,changed_by) VALUES($1,'served','bill_requested','Bill opened for settlement',$2)",[id,req.user.name]);if(order.table_id)await client.query("UPDATE restaurant_tables SET status='waiting_for_bill' WHERE id=$1",[order.table_id]);order={...order,status:'bill_requested'}}const sale=await ensureRestaurantSale(client,bid,order,req.user.name);const posted=await postPaymentLines(client,{bid,branchId:order.branch_id,customerId:order.customer_id,sourceType:'restaurant_order',sourceId:id,total:order.total,lines,userName:req.user.name});const all=await paymentSummaryForSource(client,bid,'restaurant_order',id);const methods=[...new Set(all.payments.filter(x=>x.status==='posted').map(x=>x.payment_method))],method=methods.length===1?methods[0]:methods.length>1?'split':'pending',tendered=all.payments.filter(x=>x.status==='posted').reduce((n,x)=>n+Number(x.tendered_amount||0),0),change=all.payments.filter(x=>x.status==='posted').reduce((n,x)=>n+Number(x.change_amount||0),0),newStatus=posted.status==='paid'?'paid':'partially_paid';const previous=order.status;const u=await client.query("UPDATE restaurant_orders SET amount_paid=$1,balance_due=$2,status=$3,held=false,updated_at=now() WHERE id=$4 RETURNING *",[posted.paid,posted.balance,newStatus,id]);await client.query("UPDATE sales SET payment_method=$1,payment_status=$2,amount_paid=$3,balance_due=$4,tendered_amount=$5,change_amount=$6 WHERE id=$7",[method,posted.status,posted.paid,posted.balance,tendered,change,sale.id]);if(previous!==newStatus)await client.query('INSERT INTO restaurant_order_status_history(order_id,from_status,to_status,comment,changed_by) VALUES($1,$2,$3,$4,$5)',[id,previous,newStatus,newStatus==='paid'?'Bill fully settled':'Partial payment posted',req.user.name]);await client.query('COMMIT');await audit(req.user,bid,'payment','restaurant_order',id,{amount:posted.posted.reduce((n,x)=>n+Number(x.amount),0),amountPaid:posted.paid,balanceDue:posted.balance,status:newStatus,saleId:sale.id});res.json({order:u.rows[0],saleId:sale.id,payments:all.payments,posted:posted.posted})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.get('/api/payments/reconciliation',auth,tenant,async(req,res)=>{const bid=await getBiz(req),from=req.query.from||null,to=req.query.to||null;const q=await pool.query("SELECT payment_method,count(*)::int transactions,coalesce(sum(amount),0)::numeric amount,coalesce(sum(change_amount),0)::numeric change FROM payments WHERE business_id=$1 AND status='posted' AND ($2::date IS NULL OR received_at::date >= $2::date) AND ($3::date IS NULL OR received_at::date <= $3::date) GROUP BY payment_method ORDER BY amount DESC",[bid,from,to]);const total=q.rows.reduce((n,x)=>n+Number(x.amount||0),0);res.json({methods:q.rows,total})});

app.post('/api/restaurant/orders/:id/transfer',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),toTableId=Number(req.body?.toTableId||0),notes=req.body?.notes||null;if(!toTableId)return res.status(400).json({error:'Destination table is required'});const client=await pool.connect();try{await client.query('BEGIN');const o=await client.query("SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 AND status NOT IN ('closed','cancelled') FOR UPDATE",[id,bid]);if(!o.rowCount)throw new Error('Open order not found');const t=await client.query('SELECT * FROM restaurant_tables WHERE id=$1 AND business_id=$2 AND branch_id=$3 AND active=true FOR UPDATE',[toTableId,bid,o.rows[0].branch_id]);if(!t.rowCount)throw new Error('Destination table not found');if(['occupied','waiting_for_bill'].includes(t.rows[0].status))throw new Error('Destination table is occupied');const from=o.rows[0].table_id;await client.query("UPDATE restaurant_orders SET table_id=$1,order_type='dine_in',updated_at=now() WHERE id=$2",[toTableId,id]);await client.query("UPDATE restaurant_tables SET status='occupied' WHERE id=$1",[toTableId]);await freeRestaurantTableIfUnused(client,bid,from,id);await client.query("INSERT INTO restaurant_order_transfers(order_id,from_table_id,to_table_id,action_type,notes,changed_by) VALUES($1,$2,$3,'transfer',$4,$5)",[id,from,toTableId,notes,req.user.name]);await client.query('COMMIT');res.json({ok:true})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.post('/api/restaurant/orders/:id/merge',auth,tenant,async(req,res)=>{const bid=await getBiz(req),targetId=Number(req.params.id),sourceId=Number(req.body?.sourceOrderId||0);if(!sourceId||sourceId===targetId)return res.status(400).json({error:'A different source order is required'});const client=await pool.connect();try{await client.query('BEGIN');const orders=await client.query("SELECT * FROM restaurant_orders WHERE business_id=$1 AND id=ANY($2::bigint[]) AND status NOT IN ('closed','cancelled','paid') FOR UPDATE",[bid,[targetId,sourceId]]);if(orders.rowCount!==2)throw new Error('Both orders must be open');const target=orders.rows.find(x=>Number(x.id)===targetId),source=orders.rows.find(x=>Number(x.id)===sourceId);await client.query('UPDATE restaurant_order_items SET order_id=$1 WHERE order_id=$2',[targetId,sourceId]);await recalcRestaurantOrder(client,targetId);await client.query("UPDATE restaurant_orders SET status='cancelled',notes=concat(coalesce(notes,''),' Merged into ', $1),closed_at=now(),updated_at=now() WHERE id=$2",[target.order_no,sourceId]);await client.query("INSERT INTO restaurant_order_transfers(order_id,from_table_id,to_table_id,action_type,notes,changed_by) VALUES($1,$2,$3,'merge',$4,$5)",[targetId,source.table_id,target.table_id,'Merged order '+source.order_no,req.user.name]);await freeRestaurantTableIfUnused(client,bid,source.table_id,sourceId);await client.query('COMMIT');res.json({ok:true,targetOrderId:targetId})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.post('/api/restaurant/orders/:id/split',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),splits=Array.isArray(req.body?.items)?req.body.items:[];if(!splits.length)return res.status(400).json({error:'Select items to split'});const client=await pool.connect();try{await client.query('BEGIN');const o=await client.query("SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 AND status NOT IN ('closed','cancelled','paid') FOR UPDATE",[id,bid]);if(!o.rowCount)throw new Error('Open order not found');const newNo=makeDocNo('ORD');const n=await client.query("INSERT INTO restaurant_orders(business_id,branch_id,order_no,order_type,table_id,customer_id,guest_count,waiter_user_id,waiter_name,status,notes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,'open',$10,$11) RETURNING *",[bid,o.rows[0].branch_id,newNo,o.rows[0].order_type,o.rows[0].table_id,o.rows[0].customer_id,o.rows[0].guest_count,o.rows[0].waiter_user_id,o.rows[0].waiter_name,'Split from '+o.rows[0].order_no,req.user.name]);for(const sp of splits){const itemId=Number(sp.itemId),qty=Number(sp.qty);const item=await client.query('SELECT * FROM restaurant_order_items WHERE id=$1 AND order_id=$2 FOR UPDATE',[itemId,id]);if(!item.rowCount||!(qty>0)||qty>Number(item.rows[0].qty))throw new Error('Invalid split quantity');if(Math.abs(qty-Number(item.rows[0].qty))<0.000001){await client.query('UPDATE restaurant_order_items SET order_id=$1 WHERE id=$2',[n.rows[0].id,itemId])}else{const ni=await client.query("INSERT INTO restaurant_order_items(order_id,product_id,menu_item_id,variant_id,product_name,variant_name,qty,unit_price,unit_cost,line_total,status,notes) SELECT $1,product_id,menu_item_id,variant_id,product_name,variant_name,$2,unit_price,unit_cost,unit_price*$2,status,notes FROM restaurant_order_items WHERE id=$3 RETURNING id",[n.rows[0].id,qty,itemId]);const mods=await client.query('SELECT * FROM restaurant_order_item_modifiers WHERE order_item_id=$1',[itemId]);for(const m of mods.rows)await client.query('INSERT INTO restaurant_order_item_modifiers(order_item_id,modifier_id,modifier_name,qty,unit_price,line_total) VALUES($1,$2,$3,$4,$5,$6)',[ni.rows[0].id,m.modifier_id,m.modifier_name,qty,m.unit_price,qty*Number(m.unit_price)]);const remain=Number(item.rows[0].qty)-qty,ratio=remain/Number(item.rows[0].qty);await client.query('UPDATE restaurant_order_items SET qty=$1,line_total=unit_price*$1 WHERE id=$2',[remain,itemId]);await client.query('UPDATE restaurant_order_item_modifiers SET qty=qty*$1,line_total=unit_price*(qty*$1) WHERE order_item_id=$2',[ratio,itemId])}}await recalcRestaurantOrder(client,id);await recalcRestaurantOrder(client,n.rows[0].id);await client.query("INSERT INTO restaurant_order_status_history(order_id,from_status,to_status,comment,changed_by) VALUES($1,NULL,'open',$2,$3)",[n.rows[0].id,'Split from '+o.rows[0].order_no,req.user.name]);await client.query('COMMIT');res.json({ok:true,newOrder:n.rows[0]})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});


app.post('/api/restaurant/orders/:id/request-cancel',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),comment=String(req.body?.comment||'').trim(),priority=req.body?.urgent?'urgent':'normal';if(!comment)return res.status(400).json({error:'Cancellation reason is required'});const client=await pool.connect();try{await client.query('BEGIN');const o=await client.query("SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 AND status NOT IN ('closed','cancelled','paid') FOR UPDATE",[id,bid]);if(!o.rowCount)throw new Error('Order cannot be cancelled');const existing=await client.query("SELECT id FROM approval_requests WHERE business_id=$1 AND action_type='restaurant_order_cancel' AND entity_type='restaurant_order' AND entity_id=$2 AND status='pending'",[bid,id]);if(existing.rowCount)throw new Error('Cancellation is already awaiting approval');const target=await approvalTarget(client,bid,'restaurant_order_cancel');const ar=await client.query("INSERT INTO approval_requests(business_id,section,action_type,entity_type,entity_id,reference_no,title,amount,requested_by_user_id,requested_by_name,approver_user_id,approver_role,status,request_comment,priority) VALUES($1,'Restaurant','restaurant_order_cancel','restaurant_order',$2,$3,$4,$5,$6,$7,$8,$9,'pending',$10,$11) RETURNING *",[bid,id,o.rows[0].order_no,'Cancel Restaurant Order '+o.rows[0].order_no,o.rows[0].total,req.user.id,req.user.name,target.approverUserId,target.approverRole,comment,priority]);await client.query('COMMIT');await audit(req.user,bid,'request_approval','restaurant_order',id,{approvalRequestId:ar.rows[0].id,action:'cancel'});res.json({ok:true,approval:ar.rows[0]})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.post('/api/restaurant/orders/:id/reopen',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),role=await getBusinessRole(req,bid);if(req.user.role!=='saas_admin'&&!['owner','admin'].includes(role||''))return res.status(403).json({error:'Only management can reopen a cancelled order'});const client=await pool.connect();try{await client.query('BEGIN');const o=await client.query("SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 AND status='cancelled' FOR UPDATE",[id,bid]);if(!o.rowCount)throw new Error('Only cancelled orders can be reopened');if(o.rows[0].table_id){const t=await client.query('SELECT status FROM restaurant_tables WHERE id=$1 AND business_id=$2 FOR UPDATE',[o.rows[0].table_id,bid]);if(t.rowCount&&['occupied','waiting_for_bill'].includes(t.rows[0].status))throw new Error('The original table is currently occupied');await client.query("UPDATE restaurant_tables SET status='occupied' WHERE id=$1",[o.rows[0].table_id])}await client.query("UPDATE restaurant_orders SET status='open',held=false,closed_at=null,updated_at=now() WHERE id=$1",[id]);await client.query("INSERT INTO restaurant_order_status_history(order_id,from_status,to_status,comment,changed_by) VALUES($1,'cancelled','open',$2,$3)",[id,req.body?.comment||'Reopened by management',req.user.name]);await client.query('COMMIT');await audit(req.user,bid,'reopen','restaurant_order',id,{});res.json({ok:true,status:'open'})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});


app.post('/api/restaurant/orders/:id/send-kitchen',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),priority=req.body?.priority==='rush'?'rush':'normal',client=await pool.connect();try{await client.query('BEGIN');const tickets=await createKitchenDelta(client,bid,id,req.user.name,priority);await client.query('COMMIT');await audit(req.user,bid,'send_kitchen','restaurant_order',id,{tickets:tickets.map(x=>x.ticket_no),priority});res.json({ok:true,tickets})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.get('/api/kitchen/tickets',auth,tenant,async(req,res)=>{const bid=await getBiz(req),stationId=Number(req.query.stationId||0),status=req.query.status||'active';const p=[bid];let where="kt.business_id=$1";if(stationId){p.push(stationId);where+=" AND kt.station_id=$2"}if(status==='active')where+=" AND kt.status IN ('new','preparing','ready')";else if(status!=='all'){p.push(status);where+=" AND kt.status=$"+p.length}const q=await pool.query("SELECT kt.*,ks.name station_name,ks.station_type,o.order_no,o.order_type,o.waiter_name,t.name table_name,extract(epoch from (now()-kt.created_at))/60 elapsed_minutes,coalesce(json_agg(json_build_object('id',ki.id,'orderItemId',ki.order_item_id,'name',ki.product_name,'qty',ki.qty,'notes',ki.notes,'status',ki.status,'startedAt',ki.started_at,'readyAt',ki.ready_at,'servedAt',ki.served_at) ORDER BY ki.id) FILTER (WHERE ki.id IS NOT NULL),'[]'::json) items FROM kitchen_tickets kt LEFT JOIN kitchen_stations ks ON ks.id=kt.station_id JOIN restaurant_orders o ON o.id=kt.order_id LEFT JOIN restaurant_tables t ON t.id=o.table_id LEFT JOIN kitchen_ticket_items ki ON ki.ticket_id=kt.id WHERE "+where+" GROUP BY kt.id,ks.name,ks.station_type,o.order_no,o.order_type,o.waiter_name,t.name ORDER BY CASE kt.priority WHEN 'rush' THEN 0 ELSE 1 END,kt.created_at",[...p]);res.json(q.rows)});
app.get('/api/kitchen/history',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT kt.*,ks.name station_name,o.order_no,t.name table_name FROM kitchen_tickets kt LEFT JOIN kitchen_stations ks ON ks.id=kt.station_id JOIN restaurant_orders o ON o.id=kt.order_id LEFT JOIN restaurant_tables t ON t.id=o.table_id WHERE kt.business_id=$1 ORDER BY kt.id DESC LIMIT 250",[bid]);res.json(q.rows)});
app.put('/api/kitchen/tickets/:id/status',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),to=String(req.body?.status||''),client=await pool.connect();const allowed={new:['preparing'],preparing:['ready'],ready:['served']};try{await client.query('BEGIN');const t=await client.query('SELECT * FROM kitchen_tickets WHERE id=$1 AND business_id=$2 FOR UPDATE',[id,bid]);if(!t.rowCount)throw new Error('Kitchen ticket not found');if(!(allowed[t.rows[0].status]||[]).includes(to))throw new Error('Invalid kitchen ticket transition');const nowCol=to==='preparing'?'started_at':to==='ready'?'ready_at':'completed_at';await client.query("UPDATE kitchen_tickets SET status=$1,"+nowCol+"=coalesce("+nowCol+",now()) WHERE id=$2",[to,id]);const itemCol=to==='preparing'?'started_at':to==='ready'?'ready_at':'served_at';await client.query("UPDATE kitchen_ticket_items SET status=$1,"+itemCol+"=coalesce("+itemCol+",now()) WHERE ticket_id=$2 AND status<>'served'",[to,id]);const mapped=to==='preparing'?'preparing':to==='ready'?'ready':'served';await client.query("UPDATE restaurant_order_items oi SET status=$1 FROM kitchen_ticket_items ki WHERE ki.ticket_id=$2 AND ki.order_item_id=oi.id",[mapped,id]);await client.query("INSERT INTO kitchen_events(business_id,ticket_id,event_type,from_status,to_status,changed_by) VALUES($1,$2,'ticket_status',$3,$4,$5)",[bid,id,t.rows[0].status,to,req.user.name]);const orderStatus=await syncRestaurantOrderFromKitchen(client,Number(t.rows[0].order_id));if(orderStatus&&orderStatus!==t.rows[0].status)await client.query("INSERT INTO restaurant_order_status_history(order_id,from_status,to_status,comment,changed_by) SELECT id,status,$1,'Kitchen status sync',$2 FROM restaurant_orders WHERE id=$3",[orderStatus,req.user.name,t.rows[0].order_id]);await client.query('COMMIT');res.json({ok:true,status:to,orderStatus})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.put('/api/kitchen/items/:id/status',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),to=String(req.body?.status||''),client=await pool.connect();const allowed={new:['preparing'],preparing:['ready'],ready:['served']};try{await client.query('BEGIN');const i=await client.query("SELECT ki.*,kt.business_id,kt.order_id,kt.id ticket_id FROM kitchen_ticket_items ki JOIN kitchen_tickets kt ON kt.id=ki.ticket_id WHERE ki.id=$1 AND kt.business_id=$2 FOR UPDATE OF ki,kt",[id,bid]);if(!i.rowCount)throw new Error('Kitchen item not found');if(!(allowed[i.rows[0].status]||[]).includes(to))throw new Error('Invalid kitchen item transition');const col=to==='preparing'?'started_at':to==='ready'?'ready_at':'served_at';await client.query("UPDATE kitchen_ticket_items SET status=$1,"+col+"=coalesce("+col+",now()) WHERE id=$2",[to,id]);await client.query("UPDATE restaurant_order_items SET status=$1 WHERE id=$2",[to==='preparing'?'preparing':to==='ready'?'ready':'served',i.rows[0].order_item_id]);const ticket=await client.query("SELECT count(*) FILTER (WHERE status='new')::int n,count(*) FILTER (WHERE status='preparing')::int p,count(*) FILTER (WHERE status='ready')::int r,count(*) FILTER (WHERE status='served')::int s,count(*)::int total FROM kitchen_ticket_items WHERE ticket_id=$1",[i.rows[0].ticket_id]);const x=ticket.rows[0];let ticketStatus=x.s===x.total?'served':(x.r+x.s===x.total?'ready':(x.p+x.r+x.s>0?'preparing':'new'));await client.query("UPDATE kitchen_tickets SET status=$1,started_at=CASE WHEN $1='preparing' THEN coalesce(started_at,now()) ELSE started_at END,ready_at=CASE WHEN $1='ready' THEN coalesce(ready_at,now()) ELSE ready_at END,completed_at=CASE WHEN $1='served' THEN coalesce(completed_at,now()) ELSE completed_at END WHERE id=$2",[ticketStatus,i.rows[0].ticket_id]);await client.query("INSERT INTO kitchen_events(business_id,ticket_id,order_item_id,event_type,from_status,to_status,changed_by) VALUES($1,$2,$3,'item_status',$4,$5,$6)",[bid,i.rows[0].ticket_id,i.rows[0].order_item_id,i.rows[0].status,to,req.user.name]);await syncRestaurantOrderFromKitchen(client,Number(i.rows[0].order_id));await client.query('COMMIT');res.json({ok:true,status:to,ticketStatus})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.put('/api/kitchen/tickets/:id/priority',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),priority=req.body?.priority==='rush'?'rush':'normal';const q=await pool.query('UPDATE kitchen_tickets SET priority=$1 WHERE id=$2 AND business_id=$3 RETURNING *',[priority,id,bid]);if(!q.rowCount)return res.status(404).json({error:'Kitchen ticket not found'});await pool.query("INSERT INTO kitchen_events(business_id,ticket_id,event_type,to_status,changed_by) VALUES($1,$2,'priority',$3,$4)",[bid,id,priority,req.user.name]);res.json(q.rows[0])});
