app.put('/api/restaurant/orders/:id/charges',auth,tenant,async(req,res)=>{const bid=await getBiz(req),id=Number(req.params.id),{taxRate=null,serviceRate=null,tip=0,taxInclusive=null}=req.body||{},client=await pool.connect();try{await client.query('BEGIN');const o=await client.query("SELECT * FROM restaurant_orders WHERE id=$1 AND business_id=$2 AND status NOT IN ('bill_requested','partially_paid','paid','closed','cancelled') FOR UPDATE",[id,bid]);if(!o.rowCount)throw new Error('Order charges can no longer be changed');const b=await client.query('SELECT default_tax_rate,tax_inclusive,default_service_charge_rate FROM businesses WHERE id=$1',[bid]);const tr=Math.max(0,Number(taxRate??b.rows[0]?.default_tax_rate??0)),sr=Math.max(0,Number(serviceRate??b.rows[0]?.default_service_charge_rate??0)),inclusive=taxInclusive===null||taxInclusive===undefined?!!b.rows[0]?.tax_inclusive:!!taxInclusive,base=Math.max(0,Number(o.rows[0].subtotal)-Number(o.rows[0].discount||0)),tax=tr>0?(inclusive?base-(base/(1+tr/100)):base*tr/100):0,service=base*sr/100,tipAmount=Math.max(0,Number(tip||0));await client.query('UPDATE restaurant_orders SET tax=$1,service_charge=$2,tip=$3,tax_inclusive=$4,updated_at=now() WHERE id=$5',[tax,service,tipAmount,inclusive,id]);const totals=await recalcRestaurantOrder(client,id);await client.query('COMMIT');await audit(req.user,bid,'update_charges','restaurant_order',id,{taxRate:tr,taxInclusive:inclusive,serviceRate:sr,tip:tipAmount});res.json({...totals,tax,serviceCharge:service,tip:tipAmount,taxInclusive:inclusive})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

