app.post('/api/branches',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const client=await pool.connect();try{await client.query('BEGIN');const q=await client.query('INSERT INTO branches(business_id,name,location) VALUES($1,$2,$3) RETURNING *',[bid,req.body.name,req.body.location||null]);await client.query("INSERT INTO inventory_locations(business_id,branch_id,name,location_type,is_default) VALUES($1,$2,'Main Store','main',true)",[bid,q.rows[0].id]);await client.query('COMMIT');res.json(q.rows[0])}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
