app.post('/api/cash/open',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const open=await pool.query("SELECT id FROM cash_sessions WHERE business_id=$1 AND status='open' ORDER BY id DESC LIMIT 1",[bid]);if(open.rowCount)return res.status(400).json({error:'Cash session already open'});const q=await pool.query("INSERT INTO cash_sessions(business_id,opened_by,opening_cash,status) VALUES($1,$2,$3,'open') RETURNING *",[bid,req.user.name,Number(req.body.openingCash||0)]);res.json(q.rows[0])});
app.get('/api/cash/current',auth,tenant,async(req,res)=>{const bid=await getBiz(req);const q=await pool.query("SELECT * FROM cash_sessions WHERE business_id=$1 AND status='open' ORDER BY id DESC LIMIT 1",[bid]);res.json(q.rows[0]||null)});
app.post('/api/cash/close',auth,tenant,async(req,res)=>{const bid=await getBiz(req),q=await pool.query("SELECT * FROM cash_sessions WHERE business_id=$1 AND status='open' ORDER BY id DESC LIMIT 1",[bid]);if(!q.rowCount)return res.status(404).json({error:'No open cash session'});const s=q.rows[0],ledger=await pool.query("SELECT coalesce(sum(pa.amount),0)::numeric x FROM payment_allocations pa JOIN payments p ON p.id=pa.payment_id WHERE pa.business_id=$1 AND p.status='posted' AND p.payment_method='cash' AND p.received_at >= $2",[bid,s.opened_at]),legacy=await pool.query("SELECT coalesce(sum(sa.total),0)::numeric x FROM sales sa WHERE sa.business_id=$1 AND sa.created_at >= $2 AND sa.payment_method='cash' AND NOT EXISTS(SELECT 1 FROM payment_allocations pa WHERE pa.business_id=$1 AND pa.source_type='sale' AND pa.source_id=sa.id)",[bid,s.opened_at]),expected=Number(s.opening_cash)+Number(ledger.rows[0].x)+Number(legacy.rows[0].x),actual=Number(req.body.actualCash??req.body.closingCash??0),u=await pool.query("UPDATE cash_sessions SET closing_cash=$1,expected_cash=$2,status='closed',closed_at=now() WHERE id=$3 RETURNING *",[actual,expected,s.id]);res.json({...u.rows[0],variance:actual-expected})});
